#!/usr/bin/env python3
"""Original v0.26 scenarios. Regenerate from any working directory.
Each scene has three decisions, multiple outcomes, explicit eligibility and named
follow-ups. Job/major scenes describe the work rather than reskinning random wins.
"""
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[2]
EVENTS, ECHOES = [], []

def O(text, effects=None, weight=1, **kwargs):
    return dict(text=text, effects=effects or {}, weight=weight, **kwargs)

def C(label, a, b, **kwargs):
    return dict(label=label, outcomes=[a, b], **kwargs)

def E(key, title, text, conditions, choices, themes, icon='🌱', **kwargs):
    assert len(choices) >= 3 and all(len(c['outcomes']) >= 2 for c in choices)
    e = dict(id='ctx.'+key, icon=icon, title=title, text=text, conditions={'life':['human','royal','vampire','witch','super','revenant'], **conditions}, choices=choices, themes=themes, weight=5, cooldown=7, **kwargs)
    EVENTS.append(e)
    return e

def echo(source, title, text, cond=None):
    key=source['id']+'.echo'
    # Consequences exist only when the triggering choice actually happened.
    source['choices'][0]['outcomes'][0]['schedule']={'event':key, 'years':[1,3]}
    ECHOES.append(dict(id=key, icon='📬', title=title, text=text,
        conditions={'life':['human','royal','vampire','witch','super','revenant'], **(cond or {})}, followup_only=True, weight=1,
        choices=[
            C('Follow through', O('I kept the promise when it had stopped being exciting. Somebody noticed.',{'happiness':4,'karma':2,'stress':2}), O('I tried to follow through, but the circumstances had changed. It still took effort.',{'stress':3,'smarts':1})),
            C('Renegotiate what I can do', O('I explained what had changed. We found a smaller version that still mattered.',{'stress':-3,'happiness':2}), O('They heard an excuse where I meant an explanation.',{'happiness':-3,'stress':2})),
            C('Let it go', O('I let that chapter close. Relief and regret arrived together.',{'stress':-3,'happiness':-1}), O('The chance went to somebody else. I was more disappointed than I expected.',{'happiness':-4,'smarts':1}))]))

