job_file=ROOT/'data/jobs.json'
base_jobs=[j for j in json.loads(job_file.read_text()) if j['id'] not in {x[0] for x in JOBS}]
for jid,field,salary,edu,majors,ranks,problem,a,b,c,opportunity in JOBS:
    regulated=jid in ['public_defender','special_education','community_nurse','biomedical_engineer']
    jd=dict(id=jid,field=field,salary=salary,edu=edu,min_age=22 if edu=='graduate' else 18,
            stress=4,ranks=ranks.split('|'),icon='🧰',preferred_majors=majors)
    if regulated: jd['majors']=majors
    years={'data_analyst':1960,'web_designer':1995,'cybersecurity':1980,'renewable_technician':1980,'paramedic':1960,'lab_technician':1900,'mental_health':1920,'logistics_planner':1920,'compliance':1930,'biomedical_engineer':1950,'special_education':1900}
    if jid in years: jd['era_min']=years[jid]
    if field=='Tech': jd['local_scenes']=['tech','studio']
    if field in ['Food','Hospitality']: jd['local_scenes']=['restaurant']
    if field in ['Engineering','Trades','Energy']: jd['local_scenes']=['construction']
    base_jobs.append(jd)
    scene=E('job.'+jid, 'The part the job advert left out', problem, {'age':[18,85],'job':jid}, [
        C(a, O('I did the careful work. It delayed the easy answer, but the result held up when somebody checked.', {'job_perf':5,'stress':3,'karma':2},2,stat_bonus={'smarts':.35}), O('I was right to check, but the delay still landed on me. Being careful did not make the deadline disappear.',{'job_perf':-2,'stress':5,'smarts':1})),
        C(b, O('We found a compromise that people could actually use. I learned who was willing to help.',{'job_perf':3,'happiness':2,'stress':1},2), O('The compromise left everyone slightly dissatisfied. I had to explain it twice.',{'job_perf':-1,'stress':4})),
        C(c, O('Nobody asked another question that day. I knew that was not the same as getting it right.',{'stress':-2,'karma':-2}), O('The shortcut surfaced at the worst possible moment. I had to own it.',{'job_perf':-7,'stress':7,'happiness':-3},2))], ['work'],icon='💼')
    echo(scene, 'The work came back', 'The decision you made on the job has reached the next team. They want to know whether you will stand behind it.', {'employed':True})
    E('job.'+jid+'.opportunity','Something worth doing',opportunity,{'age':[18,85],'job':jid},[
        C('Take responsibility for it', O('I made something useful rather than merely presentable. I kept the work as evidence of what I could do.',{'job_perf':5,'stress':3,'happiness':3},2,market={'training':{'field':field}}), O('I took it on and underestimated the hours. I learned, but the rest of my work slipped.',{'job_perf':-2,'stress':6,'smarts':1})),
        C('Share it with a colleague', O('We divided the work properly. Sharing credit was easier than carrying it alone.',{'job_perf':3,'stress':-2,'happiness':2}), O('We each assumed the other had finished the last piece. I will write down responsibilities next time.',{'job_perf':-3,'stress':4})),
        C('Keep to my normal workload', O('I protected my evenings. It was a reasonable decision, even if somebody else got the credit.',{'stress':-3,'happiness':1}), O('I watched the opportunity become someone else\'s promotion story.',{'happiness':-3,'stress':1}))],['work'],icon='🧰')
job_file.write_text(json.dumps(base_jobs,ensure_ascii=False,indent=1)+'\n')

